function setLanguage(lang) {
  currentLanguage = ['ru','uk','en','kk'].includes(lang) ? lang : 'ru';
  try { localStorage.setItem('zeroengine-language', currentLanguage); } catch {}
  document.documentElement.lang = currentLanguage;
  ['#language-select-home','#language-select-editor'].forEach(sel => { const el=$(sel); if(el) el.value=currentLanguage; });
  translateDocument();
}
function translateDocument(root=document) {
  if (translatingNow) return;
  translatingNow = true;
  const dictionary = I18N[currentLanguage] || {};
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const raw = node.nodeValue;
    if (!raw || !raw.trim()) continue;
    let source = originalTextNodes.get(node);
    if (!source || raw !== lastTranslatedTextNodes.get(node)) { source = raw; originalTextNodes.set(node, source); }
    const leading = source.match(/^\s*/)?.[0] || '', trailing = source.match(/\s*$/)?.[0] || '';
    const core = source.trim();
    const result = dictionary[core] ?? core;
    const translated = leading + result + trailing;
    if (node.nodeValue !== translated) node.nodeValue = translated;
    lastTranslatedTextNodes.set(node, translated);
  }
  const elements = root.querySelectorAll ? root.querySelectorAll('[placeholder],[title],[aria-label]') : [];
  for (const el of elements) for (const attr of ['placeholder','title','aria-label']) {
    if (!el.hasAttribute(attr)) continue;
    let map = originalAttributes.get(el); if (!map) { map={}; originalAttributes.set(el,map); }
    let last = lastTranslatedAttributes.get(el); if (!last) { last={}; lastTranslatedAttributes.set(el,last); }
    const raw = el.getAttribute(attr);
    if (map[attr] == null || raw !== last[attr]) map[attr] = raw;
    const translated = dictionary[map[attr]] ?? map[attr];
    if (raw !== translated) el.setAttribute(attr,translated);
    last[attr] = translated;
  }
  translatingNow = false;
}
function startLocalizationObserver() {
  if (localizationObserver) localizationObserver.disconnect();
  localizationObserver = new MutationObserver(() => translateDocument());
  localizationObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
  translateDocument();
}

// ---------- Local project storage ----------
function openDatabase() {
  return new Promise((resolve, reject) => {
    if (!('indexedDB' in window)) return reject(new Error('IndexedDB недоступен в этом браузере'));
    const request = indexedDB.open('ZeroEngineDB', 1);
    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains('projects')) database.createObjectStore('projects', { keyPath: 'id' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Не удалось открыть хранилище'));
  });
}
function dbRequest(mode, action) {
  return new Promise((resolve, reject) => {
    if (!db) return reject(new Error('Локальное хранилище не готово'));
    const transaction = db.transaction('projects', mode);
    const store = transaction.objectStore('projects');
    const request = action(store);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}
const getAllProjects = () => dbRequest('readonly', store => store.getAll());
const putProject = project => dbRequest('readwrite', store => store.put(project));
const deleteProjectRecord = id => dbRequest('readwrite', store => store.delete(id));

function makeProject(name, description, targetPlatform='cross-platform', baseResolution={width:1920,height:1080}) {
  const sceneData = DEFAULT_SCENE();
  return {
    id: uid(), name: name.trim(), description: description.trim(), targetPlatform, baseResolution: {width:Number(baseResolution.width)||1920,height:Number(baseResolution.height)||1080},
    createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
    activeSceneId: sceneData.id, scenes: [{ id: sceneData.id, name: sceneData.name, data: sceneData }],
    assets: [], materials: [], scripts: [], assetFolders: [], zeroBoxes: [], uiElements: [], variables: [{id:uid(),name:'Value',type:'Number',value:0,system:true}]
  };
}
function activeScene() { return currentProject?.scenes.find(item => item.id === currentProject.activeSceneId) || currentProject?.scenes[0]; }
function activeSceneData() { return activeScene()?.data; }
function normalizeProject(project) {
  project.targetPlatform ||= 'cross-platform';
  project.baseResolution ||= {width:1920,height:1080};
  project.baseResolution.width = Math.max(240, Number(project.baseResolution.width)||1920);
  project.baseResolution.height = Math.max(240, Number(project.baseResolution.height)||1080);
  if (!project.scenes?.length) {
    const data = project.scene || DEFAULT_SCENE();
    project.scenes = [{ id: data.id || uid(), name: data.name || 'Main Scene', data }];
    project.activeSceneId = project.scenes[0].id;
  }
  project.scenes.forEach(item => {
    item.data ||= { ...DEFAULT_SCENE(), id: item.id, name: item.name, objects: [] };
    item.data.objects ||= [];
    // Clean up legacy editor starter lights, but preserve user-created lights.
    const legacyLightNames = new Set(['ambient light','default light','startup light','key light']);
    item.data.objects = item.data.objects.filter(entity => !(entity.type === 'light' && (entity.editorDefault === true || legacyLightNames.has(String(entity.name||'').trim().toLowerCase()))) && entity.editorVoidFloor !== true);
  });
  project.assets ||= [];
  project.materials ||= [];
  project.scripts ||= [];
  project.assetFolders ||= [];
  project.zeroBoxes ||= [];
  project.uiElements ||= [];
  project.uiScreens ||= [];
  if (!project.uiScreens.length) project.uiScreens.push({id:uid(),name:'Главный экран',elements:clone(project.uiElements)});
  project.activeUIScreenId ||= project.uiScreens[0].id;
  const activeScreen=project.uiScreens.find(screen=>screen.id===project.activeUIScreenId)||project.uiScreens[0];
  if(activeScreen)project.activeUIScreenId=activeScreen.id;
  if (activeScreen && (!project.uiElements.length || project.uiElements===undefined)) project.uiElements=clone(activeScreen.elements||[]);
  project.variables ||= [];
  if (!project.variables.some(v => v.name === 'Value')) project.variables.unshift({id:uid(),name:'Value',type:'Number',value:0,system:true});
  const activeScreenForLoad=project.uiScreens.find(screen=>screen.id===project.activeUIScreenId)||project.uiScreens[0];
  if(activeScreenForLoad) project.uiElements=clone(activeScreenForLoad.elements||project.uiElements||[]);
  project.zeroBoxes.forEach(box => { box.blocks ||= []; box.blocks=box.blocks.filter(block=>block.type!=='Walking'); box.variables ||= []; box.connections ||= []; box.blocks.forEach((block,index)=>{ block.config ||= {...ZEROBOX_DEFAULTS}; if(block.config.variableY===undefined&&block.config.variableZ!==undefined)block.config.variableY=block.config.variableZ; if(!Number.isFinite(block.x)) block.x=360+(index%3)*330; if(!Number.isFinite(block.y)) block.y=130+Math.floor(index/3)*250; }); box.connections=box.connections.filter(c=>box.blocks.some(b=>b.id===c.from?.nodeId)&&box.blocks.some(b=>b.id===c.to?.nodeId)); });
  project.scenes.forEach(sceneItem => {
    (sceneItem.data.objects || []).forEach(entity => {
    if (entity.type === 'skybox') {
      entity.skybox ||= { shape:'sphere', tileX:1, tileY:1, smoothing:true, rotationY:0, brightness:1 };
      if (!entity.assetId && sceneItem.data.skyboxAssetId) entity.assetId = sceneItem.data.skyboxAssetId;
      entity.skybox.shape = ['sphere','box'].includes(entity.skybox.shape) ? entity.skybox.shape : 'sphere';
      entity.skybox.tileX = Math.max(.05, Number(entity.skybox.tileX)||1);
      entity.skybox.tileY = Math.max(.05, Number(entity.skybox.tileY)||1);
      entity.skybox.smoothing = entity.skybox.smoothing !== false;
      entity.skybox.rotationY = Number(entity.skybox.rotationY)||0;
      entity.skybox.brightness = Math.max(0, Math.min(3, Number(entity.skybox.brightness??1)));
    }
    if (entity.type === 'player') {
      if (!entity.cameraMount) {
        if (entity.name === 'Player Start') { entity.type = 'spawn'; entity.gameVisible = false; }
        else entity.cameraMount = { mode: 'back', offset: [0, 1.55, 3.2], fov: 70 };
      }
      if (entity.cameraMount) {
        entity.cameraMount.mode = ['head','back','top','custom'].includes(entity.cameraMount.mode) ? entity.cameraMount.mode : 'back';
        const modeDefaults={head:[0,1.6,0],back:[0,1.55,3.2],top:[0,5,0],custom:[0,1.6,0]};
        if(!Array.isArray(entity.cameraMount.offset))entity.cameraMount.offset=[...(modeDefaults[entity.cameraMount.mode]||modeDefaults.back)];
        else if(entity.cameraMount.mode==='back'&&entity.cameraMount.offset.length===3&&entity.cameraMount.offset[2]===0)entity.cameraMount.offset=[0,1.55,3.2];
        else if(entity.cameraMount.mode==='top'&&entity.cameraMount.offset.length===3&&entity.cameraMount.offset[1]===1.6)entity.cameraMount.offset=[0,5,0];
        entity.cameraMount.fov ||= 70;
        // Remove obsolete projection settings from projects created in older versions.
        delete entity.cameraMount.viewMode;
        delete entity.cameraMount.orbitOffset;
      }
    }
    if (entity.type === 'playerStart') entity.type = 'spawn';
    if (entity.type === 'spawn' && entity.gameVisible == null) entity.gameVisible = false;
    if (entity.type === 'model' && entity.unitScaleApplied == null) entity.unitScaleApplied = false;
    if (!entity.collision) entity.collision = entity.type === 'player' ? { enabled: true, shape: 'capsule', size: [.6,1.8,.6], offset: [0,.9,0], isTrigger: false } : ['primitive','model'].includes(entity.type) ? { enabled: true, shape: 'box', size: [1,1,1], offset: [0,0,0], isTrigger: false, autoFit: entity.type === 'model' } : { enabled: false, shape: 'box', size: [1,1,1], offset: [0,0,0], isTrigger: false };
    if (entity.type === 'player' && !entity.playerCollisionDefaultsApplied) {
      entity.collision.enabled = true; entity.collision.shape = 'capsule';
      entity.collision.size ||= [.6,1.8,.6]; entity.collision.offset ||= [0,.9,0];
      entity.playerCollisionDefaultsApplied = true;
    }
    entity.collision.isTrigger ??= false;
    if (entity.type === 'player' && !entity.physics) entity.physics = { enabled: true, useGravity: true, mass: 1, velocity: [0,0,0], linearDamping: .05 };
    if (entity.physics) { entity.physics.velocity ||= [0,0,0]; entity.physics.useGravity ??= true; entity.physics.mass = Math.max(.01, Number(entity.physics.mass)||1); }
    });
    // Migrate legacy scene-level skybox image to the dedicated Skybox object only.
    if(sceneItem.data.skyboxAssetId){
      let skyboxObject=(sceneItem.data.objects||[]).find(entity=>entity.type==='skybox');
      if(!skyboxObject){
        skyboxObject={id:uid(),name:'Skybox',type:'skybox',assetId:sceneItem.data.skyboxAssetId,position:[0,0,0],rotation:[0,0,0],scale:[1,1,1],visible:true,skybox:{shape:'sphere',tileX:1,tileY:1,smoothing:true,rotationY:0,brightness:1},collision:{enabled:false,shape:'box',size:[1,1,1],offset:[0,0,0],isTrigger:false}};
        sceneItem.data.objects.push(skyboxObject);
      }else if(!skyboxObject.assetId)skyboxObject.assetId=sceneItem.data.skyboxAssetId;
    }
    delete sceneItem.data.skyboxAssetId;
  });
  // One-time upgrade: old primitive/model colliders were disabled 1x1x1 placeholders by default.
  // Enable only untouched default placeholders; custom collider settings remain unchanged.
  if (!project.collisionDefaultsMigratedV060) {
    const primitiveSizes = { plane:[4,.05,4], sphere:[1.4,1.4,1.4], cylinder:[1.1,1.2,1.1], cone:[1.4,1.35,1.4], capsule:[.84,1.54,.84] };
    for (const sceneItem of project.scenes) for (const entity of sceneItem.data.objects || []) {
      const collider = entity.collision;
      if (!collider || !['primitive','model'].includes(entity.type) || collider.userConfigured) continue;
      const defaultSize = (collider.size || []).length === 3 && collider.size.every(value => Math.abs(Number(value)-1)<1e-6);
      const defaultOffset = (collider.offset || [0,0,0]).every(value => Math.abs(Number(value)||0)<1e-6);
      if (collider.enabled === false && collider.shape === 'box' && defaultSize && defaultOffset && !collider.isTrigger) {
        collider.enabled = true;
        if (entity.type === 'primitive') collider.size = primitiveSizes[entity.primitive] || [1.2,1.2,1.2];
        if (entity.type === 'model') { collider.autoFit = true; collider.autoFitApplied = false; }
      }
    }
    project.collisionDefaultsMigratedV060 = true;
  }
  return project;
}

function localizedCount(count, kind) {
  const n=Number(count)||0;
  if(currentLanguage==='en') return `${n} ${kind==='objects'?(n===1?'object':'objects'):(n===1?'project':'projects')}`;
  if(currentLanguage==='kk') return `${n} ${kind==='objects'?'нысан':'жоба'}`;
  if(currentLanguage==='uk') { const one=n%10===1&&n%100!==11, few=[2,3,4].includes(n%10)&&![12,13,14].includes(n%100); return `${n} ${kind==='objects'?(one?'об’єкт':few?'об’єкти':'об’єктів'):(one?'проєкт':few?'проєкти':'проєктів')}`; }
  return `${n} ${kind==='objects'?(n===1?'объект':n<5?'объекта':'объектов'):(n===1?'проект':n<5?'проекта':'проектов')}`;
}

// ---------- Home / projects ----------
async function renderProjectList() {
  const list = $('#project-list');
  try {
    const projects = (await getAllProjects()).sort((a,b) => new Date(b.updatedAt) - new Date(a.updatedAt));
    $('#project-count').textContent = localizedCount(projects.length,'projects');
    if (!projects.length) {
      list.innerHTML = '<div class="empty-projects"><div class="empty-icon">▱</div><strong>Пока нет проектов</strong><span>Создай новый проект или импортируй существующий ZIP.</span></div>';
      return;
    }
    list.innerHTML = projects.map(project => `
      <article class="project-card" data-open-project="${project.id}">
        <div class="project-card-top"><span class="project-symbol">◈</span><button class="delete-project" data-delete-project="${project.id}" title="Удалить проект">×</button></div>
        <h3>${escapeHtml(project.name)}</h3><p>${escapeHtml(project.description || 'Без описания')}</p>
        <div class="project-card-foot"><span>${(project.assets || []).length} ASSETS</span><span>${new Date(project.updatedAt).toLocaleDateString('ru-RU')}</span></div>
      </article>`).join('');
    $$('[data-open-project]', list).forEach(card => card.addEventListener('click', event => {
      if (event.target.closest('[data-delete-project]')) return;
      const project = projects.find(item => item.id === card.dataset.openProject);
      if (project) openProject(project);
    }));
    $$('[data-delete-project]', list).forEach(button => button.addEventListener('click', async event => {
      event.stopPropagation();
      const id = button.dataset.deleteProject;
      const project = projects.find(item => item.id === id);
      if (!project || !confirm(`Удалить проект «${project.name}» из браузера?`)) return;
      await deleteProjectRecord(id);
      renderProjectList();
      toast('Проект удалён из браузера', 'success');
    }));
  } catch (error) {
    list.innerHTML = '<div class="empty-projects"><strong>Не удалось прочитать проекты</strong><span>Проверь, что браузер разрешает локальное хранилище.</span></div>';
    console.error(error);
  }
}
