    miniTransform=new TransformControls(miniCamera,canvas);miniTransform.setMode('translate');miniScene.add(miniTransform.getHelper());miniTransform.attach(handleGroup);miniTransform.addEventListener('dragging-changed',e=>miniOrbit.enabled=!e.value);
