const DEVICE_RESOLUTIONS = {
  desktop: [
    {label:'1920 × 1080 (Full HD)',width:1920,height:1080},
    {label:'1600 × 900',width:1600,height:900},
    {label:'1366 × 768',width:1366,height:768},
    {label:'2560 × 1440 (QHD)',width:2560,height:1440}
  ],
  'phone-portrait': [
    {label:'390 × 844 (iPhone)',width:390,height:844},
    {label:'360 × 800',width:360,height:800},
    {label:'412 × 915',width:412,height:915},
    {label:'432 × 960',width:432,height:960}
  ],
  'phone-landscape': [
    {label:'844 × 390 (iPhone)',width:844,height:390},
    {label:'800 × 360',width:800,height:360},
    {label:'915 × 412',width:915,height:412},
    {label:'960 × 432',width:960,height:432}
  ],
  tablet: [
    {label:'1024 × 768',width:1024,height:768},
    {label:'1280 × 800',width:1280,height:800},
    {label:'1180 × 820',width:1180,height:820}
  ]
};
function applyDeviceSettings(){
  const {profile,width,height}=deviceSettings;
  document.documentElement.dataset.deviceProfile=profile||'auto';
  const w=Math.max(240,Number(width)||window.innerWidth||1280),h=Math.max(240,Number(height)||window.innerHeight||720);
  document.documentElement.style.setProperty('--ui-device-aspect',`${w} / ${h}`);
  document.documentElement.style.setProperty('--ui-device-width',`${w}px`);
  document.documentElement.style.setProperty('--ui-device-height',`${h}px`);
}
function loadDeviceSettings(){
  try{const saved=JSON.parse(localStorage.getItem('zeroengine-device-settings')||'null');if(saved&&typeof saved==='object')deviceSettings={profile:['auto','desktop','tablet','phone-portrait','phone-landscape','custom'].includes(saved.profile)?saved.profile:'auto',width:Number(saved.width)||window.innerWidth||1280,height:Number(saved.height)||window.innerHeight||720};}catch{}
  applyDeviceSettings();
  window.addEventListener('resize',()=>{if(deviceSettings.profile==='auto'){deviceSettings.width=window.innerWidth||1280;deviceSettings.height=window.innerHeight||720;applyDeviceSettings();}});
}
function openDeviceSettings(){
  const profileLabels={auto:'Автоматически по экрану',desktop:'ПК / ноутбук',tablet:'Планшет', 'phone-portrait':'Телефон — вертикально','phone-landscape':'Телефон — горизонтально',custom:'Своё разрешение'};
  showModal(`<div class="modal-header"><div><span class="panel-kicker">DISPLAY SETTINGS</span><h2 id="modal-title">Устройство и разрешение</h2><p>Выбери целевой экран для макета игрового интерфейса. Сам редактор подстраивается под размер окна.</p></div><button class="modal-close" data-close-modal>×</button></div><div class="modal-body"><label class="field-label">Устройство<select id="device-profile-select" class="field-select">${Object.entries(profileLabels).map(([value,label])=>`<option value="${value}" ${deviceSettings.profile===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="field-label">Разрешение<select id="device-resolution-select" class="field-select"></select></label><div class="field-row two" id="device-custom-size"><label class="field-label">Ширина, px<input class="field-input" id="device-width-input" type="number" min="240" max="7680" step="1" value="${Math.round(deviceSettings.width)}"></label><label class="field-label">Высота, px<input class="field-input" id="device-height-input" type="number" min="240" max="7680" step="1" value="${Math.round(deviceSettings.height)}"></label></div><div class="device-preview-card"><div class="device-preview-screen" id="device-preview-screen"><span>ZEROENGINE</span></div><div><b id="device-preview-name">${profileLabels[deviceSettings.profile]}</b><small id="device-preview-dimensions">${Math.round(deviceSettings.width)} × ${Math.round(deviceSettings.height)} px</small></div></div></div><div class="modal-footer"><button class="button button-quiet" data-close-modal>Отмена</button><button class="button button-primary" id="apply-device-settings">Применить</button></div>`);
  const profile=$('#device-profile-select'),resolution=$('#device-resolution-select'),custom=$('#device-custom-size'),widthInput=$('#device-width-input'),heightInput=$('#device-height-input');
  const drawResolutionOptions=(preferCurrent=true)=>{
    const list=DEVICE_RESOLUTIONS[profile.value]||[];const target=preferCurrent?list.find(item=>item.width===Number(widthInput.value)&&item.height===Number(heightInput.value)):null;const selected=target||list[0];
    resolution.innerHTML=list.map(item=>`<option value="${item.width}x${item.height}" ${selected&&selected===item?'selected':''}>${item.label}</option>`).join('')+'<option value="custom">Пользовательское…</option>';
    if(profile.value==='custom'||profile.value==='auto')resolution.value='custom';
    if(selected){widthInput.value=selected.width;heightInput.value=selected.height;}
    custom.classList.toggle('hidden',resolution.value!=='custom'&&profile.value!=='custom'&&profile.value!=='auto');
    updateDevicePreview();
  };
  const updateDevicePreview=()=>{
    const w=Math.max(240,Number(widthInput.value)||390),h=Math.max(240,Number(heightInput.value)||844);const preview=$('#device-preview-screen');
    preview.style.aspectRatio=`${w} / ${h}`;preview.style.width=h>w?'44px':'84px';
    $('#device-preview-name').textContent=profileLabels[profile.value]||profileLabels.custom;$('#device-preview-dimensions').textContent=`${w} × ${h} px`;
  };
  profile.addEventListener('change',()=>{const p=profile.value;if(p==='auto'){widthInput.value=window.innerWidth||1280;heightInput.value=window.innerHeight||720;resolution.innerHTML='<option value="custom">Текущий экран</option>';resolution.value='custom';custom.classList.remove('hidden');updateDevicePreview();return;}if(p==='custom'){resolution.innerHTML='<option value="custom">Своё разрешение</option>';resolution.value='custom';custom.classList.remove('hidden');updateDevicePreview();return;}drawResolutionOptions(false);});
  resolution.addEventListener('change',()=>{if(resolution.value==='custom'){custom.classList.remove('hidden');}else{const [w,h]=resolution.value.split('x').map(Number);widthInput.value=w;heightInput.value=h;custom.classList.add('hidden');}updateDevicePreview();});
  [widthInput,heightInput].forEach(input=>input.addEventListener('input',()=>{if(profile.value!=='auto'&&profile.value!=='custom'&&resolution.value!=='custom')resolution.value='custom';custom.classList.remove('hidden');updateDevicePreview();}));
  drawResolutionOptions(true);
  $('#apply-device-settings').addEventListener('click',()=>{
    let width=Math.max(240,Math.min(7680,Number(widthInput.value)||390)),height=Math.max(240,Math.min(7680,Number(heightInput.value)||844));
    if(profile.value==='auto'){width=window.innerWidth||width;height=window.innerHeight||height;}
    deviceSettings={profile:profile.value,width,height};applyDeviceSettings();
    try{localStorage.setItem('zeroengine-device-settings',JSON.stringify(deviceSettings));}catch{}
    closeModal();if(workbenchMode==='interface')renderWorkbench();toast(`Устройство: ${profileLabels[profile.value]} · ${width} × ${height}`,'success');
  });
}

function getNumericInputStep(input,current){
  const raw=input.getAttribute('step');
  if(raw&&raw.toLowerCase()!=='any'){
    const declared=Number(raw);if(Number.isFinite(declared)&&declared>0)return declared;
  }
  const custom=Number(input.dataset.step);if(Number.isFinite(custom)&&custom>0)return custom;
  const abs=Math.abs(Number(current)||0);
  if(abs<.01)return .001;if(abs<.1)return .01;if(abs<1)return .1;if(abs<10)return .5;if(abs<100)return 1;if(abs<1000)return 10;if(abs<10000)return 100;return 1000;
}
function enhanceNumericInputs(root=document){
  const candidates=$$('input[type="number"]',root);
  for(const input of candidates){
    if(input.closest('.axis-stepper,.numeric-stepper')||input.dataset.stepperEnhanced==='1')continue;
    input.dataset.stepperEnhanced='1';
    const wrap=document.createElement('div');wrap.className='numeric-stepper';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);
    const make=(direction,label)=>{const button=document.createElement('button');button.type='button';button.className='numeric-step-button';button.textContent=direction<0?'−':'+';button.setAttribute('aria-label',label);button.addEventListener('click',()=>{
      const current=Number(input.value)||0,step=getNumericInputStep(input,current);
      const min=input.min!==''?Number(input.min):-Infinity,max=input.max!==''?Number(input.max):Infinity;
      const base=Number.isFinite(min)?min:0,position=(current-base)/step,epsilon=1e-9;
      const index=direction>0?Math.floor(position+epsilon)+1:Math.ceil(position-epsilon)-1;
      const stepParts=String(step).toLowerCase().split('e'),mantissaDecimals=(stepParts[0].split('.')[1]||'').length,exponent=Number(stepParts[1]||0);
      const decimals=Math.min(10,Math.max(0,mantissaDecimals-exponent));
      const next=Math.max(min,Math.min(max,Number((base+index*step).toFixed(decimals))));
      input.value=String(next);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));
    });return button;};
    wrap.appendChild(make(-1,'Уменьшить до предыдущего подходящего значения'));wrap.appendChild(input);wrap.appendChild(make(1,'Увеличить до следующего подходящего значения'));
  }
}
function initNumericSteppers(){
  enhanceNumericInputs(document);
  if(numericStepperObserver)return;
  numericStepperObserver=new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.nodeType===1){if(node.matches?.('input[type="number"]'))enhanceNumericInputs(node.parentElement||document);else if(node.querySelectorAll)enhanceNumericInputs(node);}});
  numericStepperObserver.observe(document.body,{childList:true,subtree:true});
}

function loadWorkspaceLayout(){
  try{const saved=JSON.parse(localStorage.getItem('zeroengine-workspace-layout')||'null');if(saved)workspaceLayout={...workspaceLayout,...saved};}catch{}
  applyWorkspaceLayout();
}
function applyWorkspaceLayout(){
  const layout=$('#editor-screen .editor-layout');if(!layout)return;
  layout.classList.toggle('panels-swapped',!!workspaceLayout.swapped);
  layout.classList.toggle('assets-top',!!workspaceLayout.assetsTop);
  layout.classList.toggle('workspace-hide-hierarchy',workspaceLayout.hierarchy===false);
  layout.classList.toggle('workspace-hide-inspector',workspaceLayout.inspector===false);
  layout.classList.toggle('workspace-hide-assets',workspaceLayout.assets===false);
  $('#hierarchy-panel')?.classList.toggle('workspace-hidden',workspaceLayout.hierarchy===false);
  $('#inspector-panel')?.classList.toggle('workspace-hidden',workspaceLayout.inspector===false);
  $('#asset-dock')?.classList.toggle('workspace-hidden',workspaceLayout.assets===false);
  const root=document.documentElement;
  if(Number(workspaceLayout.left)>0)root.style.setProperty('--left-w',`${workspaceLayout.left}px`);
  if(Number(workspaceLayout.right)>0)root.style.setProperty('--right-w',`${workspaceLayout.right}px`);
  if(Number(workspaceLayout.dock)>0)root.style.setProperty('--dock-h',`${workspaceLayout.dock}px`);
  requestAnimationFrame(resizeRenderer);
}
function persistWorkspaceLayout(){try{localStorage.setItem('zeroengine-workspace-layout',JSON.stringify(workspaceLayout));}catch{}}
