    for(const [a,b] of [[0,1],[1,2],[2,0]]){const ka=modelPointKey(v[a]),kb=modelPointKey(v[b]),key=[ka,kb].sort().join('|');const existing=edges.get(key);if(existing)existing.count++;else edges.set(key,{a:v[a],b:v[b],ka,kb,count:1});}
